const workerTeamRender=render;
let ownerDemo=false,ownerMember='Todas',ownerSearch='';
function ownerData(){return {repairs:state.repairs,agreements:state.supportRequests}}
function ownerPerson(r){return holder(r.id)}
function ownerLocation(r){return staffProfile(holder(r.id)).mode}
function ownerRefresh(){try{const next=JSON.parse(localStorage.getItem('hilando-v1'));if(Array.isArray(next?.repairs))state=next}catch{}initWorkScope();render();toast('Registros locales actualizados.')}
function ownerModeBar(){return '<div class="owner-mode"><span>SECCIÓN DE TRABAJO</span></div><p class="owner-local-note">Registros de este navegador. Los cambios todavía no se comparten entre celulares.</p>'}
function ownerEvents(){return (state.activity||[]).filter(a=>a.scope==='work').map((a,i)=>({...a,who:a.who||'Equipo',order:a.at||-i}))}
function ownerAlerts(){const d=ownerData();return [...d.repairs.filter(r=>r.issue).map(r=>({kind:'help',title:holder(r.id)+' necesita apoyo',description:r.issue,repair:r.id,label:'Ver arreglo',icon:'help'})),...d.repairs.filter(r=>r.stage==='review').map(r=>({kind:'quality',title:'Revisión de calidad pendiente',description:r.garment+' · '+responsibleBranch(r),repair:r.id,label:'Ver arreglo',icon:'check'}))]}
function eventCard(e){return '<div class="owner-event"><span class="event-avatar">'+esc((e.who||'E')[0])+'</span><span class="event-copy"><strong>'+esc(e.who)+'<small>'+esc(e.time)+'</small></strong><span>'+esc(e.message)+'</span></span></div>'}
function alertCard(a){return '<div class="owner-alert help"><span>'+icon(a.icon)+'</span><div><h3>'+esc(a.title)+'</h3><p>'+esc(a.description)+'</p><button onclick="ownerOpenRepair(\''+a.repair+'\')">'+esc(a.label)+' →</button></div></div>'}
function ownerKpis(){const d=ownerData();return '<div class="owner-kpis">'+[['orders',d.repairs.filter(r=>r.stage!=='delivered').length,'Trabajos activos','members'],['check',d.repairs.filter(r=>r.stage==='review').length,'Por revisar','attention'],['team',d.agreements.filter(a=>a.status==='pending').length,'Apoyos por responder','movements'],['help',d.repairs.filter(r=>r.issue).length,'Necesitan ayuda','attention']].map(([i,n,label,p])=>'<button class="owner-kpi" onclick="ownerNavigate(\''+p+'\')"><span>'+icon(i)+'</span><strong>'+n+'</strong><small>'+label+'</small></button>').join('')+'</div>'}
function memberCard(name){const rows=ownerData().repairs.filter(r=>holder(r.id)===name&&r.stage!=='delivered');return '<button class="owner-member" onclick="ownerFilterMember(\''+name+'\')"><span class="member-initial">'+esc(name[0])+'</span><span><strong>'+esc(name)+'</strong><small>'+rows.length+' trabajos asignados</small></span><b>›</b></button>'}
function ownerHome(){const events=ownerEvents(),alerts=ownerAlerts();return ownerGreeting('Así va el trabajo','Arreglos, acuerdos de apoyo y calidad del taller.')+ownerModeBar()+'<section class="owner-hero"><div><span class="owner-hero-label">EL TRABAJO DE TU EQUIPO</span><h2>Cada prenda, bien cuidada.</h2><p>Revisa los avances y ayuda a resolver las dificultades.</p><button onclick="ownerNavigate(\'members\')">Ver equipo →</button></div></section>'+ownerKpis()+'<section class="owner-surface"><div class="owner-section-title"><h2>Necesita tu atención</h2></div>'+alerts.slice(0,4).map(alertCard).join('')+(alerts.length?'':'<p>No hay asuntos pendientes.</p>')+'</section><section class="owner-surface"><div class="owner-section-title"><h2>Actividad de trabajo</h2><button onclick="ownerNavigate(\'movements\')">Ver toda →</button></div>'+events.slice(0,4).map(eventCard).join('')+(events.length?'':'<p>Los nuevos avances y acuerdos aparecerán aquí.</p>')+'</section>'}
function ownerMovementPage(){return ownerGreeting('Actividad de trabajo','Avances, acuerdos y avisos del equipo.')+ownerModeBar()+'<section class="owner-surface">'+ownerEvents().map(eventCard).join('')+'</section><h2 class="package-heading">Acuerdos de apoyo</h2>'+ownerData().agreements.map(supportCard).join('')}
function ownerOpenRepair(id){const r=ownerData().repairs.find(r=>r.id===id);if(!r)return;modal(esc(r.garment),'<p>'+r.id+' · '+esc(r.client)+'</p><p>'+esc(r.task)+'</p><p>Responsable: '+esc(holder(r.id))+'<br>Sede: '+esc(responsibleBranch(r))+'<br>Estado: '+repairLabels[r.stage]+'</p>')}
function ownerNavigate(p){selectedRepair=null;ownerSearch='';page=p;render();scrollAppTop()}
function ownerGreeting(title,sub,eyebrow='VISTA DE LA DUEÑA'){return `<div class="owner-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="sub">${sub}</p></div><button class="owner-refresh" onclick="ownerRefresh()" aria-label="Actualizar registros">↻</button></div>`}
function ownerFilterMember(name){ownerMember=name;ownerNavigate('members')}
function ownerSetMember(name){ownerMember=name;render()}
function ownerRepairRow(r){return `<button class="owner-repair-row" onclick="ownerOpenRepair('${r.id}')"><span class="owner-prenda">${icon('shirt')}</span><span><strong>${esc(r.garment)}</strong><small>${esc(r.task)} · ${r.id}</small><em>${esc(ownerLocation(r))}</em></span><span class="owner-repair-person">${esc(ownerPerson(r))}<small>${repairLabels[r.stage]||'Pendiente'}</small></span></button>`}
function ownerMembers(){const rows=ownerData().repairs.filter(r=>(ownerMember==='Todas'||ownerPerson(r)===ownerMember)&&`${r.id} ${r.client} ${r.garment} ${r.task} ${ownerPerson(r)}`.toLowerCase().includes(ownerSearch.toLowerCase()));return ownerGreeting('Cada prenda, con su responsable','Consulta responsables y avances de los arreglos.')+ownerModeBar()+`<div class="owner-members top-members">${teamPeople.map(memberCard).join('')}</div><div class="owner-filterbar">${['Todas',...teamPeople].map(p=>`<button class="${ownerMember===p?'selected':''}" onclick="ownerSetMember('${p}')">${p}</button>`).join('')}</div><input id="owner-search" class="owner-search" aria-label="Buscar prenda, cliente o trabajadora" placeholder="Buscar prenda, cliente o trabajadora…" value="${esc(ownerSearch)}"><section class="owner-surface" id="owner-repair-results">${rows.map(ownerRepairRow).join('')||'<div class="owner-empty">No hay prendas para este filtro.</div>'}</section>`}
function ownerAttentionPage(){const alerts=ownerAlerts();return ownerGreeting('Pendientes de coordinar','Revisa los avisos y la calidad pendiente.')+ownerModeBar()+`<div class="owner-attention-grid">${alerts.map(alertCard).join('')||'<div class="owner-surface owner-empty">Todo al día. No hay asuntos pendientes.</div>'}</div><p class="owner-small-print">Acuerda los siguientes pasos con las trabajadoras.</p>`}
render=function(){document.body.classList.toggle('owner-view',currentPerson==='Dueña');document.title=currentPerson==='Dueña'?'Rapicostura · Mi taller':'Rapicostura · Mi trabajo';if(currentPerson!=='Dueña'){workerTeamRender();return}if(page==='inicio')page='overview';main.innerHTML=(page==='members'?ownerMembers():page==='movements'?ownerMovementPage():page==='attention'?ownerAttentionPage():ownerHome())+personaControl();document.querySelector('.account').innerHTML='<span class="avatar">D</span><span>Dueña<small>Mi taller</small></span>';document.getElementById('mobile-nav').innerHTML=[['overview','home','Resumen'],['members','team','Equipo'],['movements','orders','Actividad'],['attention','help','Atención']].map(([p,i,label])=>'<button class="'+(page===p?'active':'')+'" onclick="ownerNavigate(\''+p+'\')">'+icon(i)+'<span>'+label+'</span></button>').join('');const input=document.getElementById('owner-search');if(input)input.oninput=e=>{ownerSearch=e.target.value;const rows=ownerData().repairs.filter(r=>(ownerMember==='Todas'||ownerPerson(r)===ownerMember)&&(r.id+' '+r.client+' '+r.garment+' '+r.task+' '+holder(r.id)).toLowerCase().includes(ownerSearch.toLowerCase()));document.getElementById('owner-repair-results').innerHTML=rows.map(ownerRepairRow).join('')||'<div class="owner-empty">No hay prendas para este filtro.</div>'}};
window.addEventListener('storage',e=>{if(e.key==='hilando-v1'&&e.newValue){try{const next=JSON.parse(e.newValue);if(Array.isArray(next.repairs)){state=next;initWorkScope();render()}}catch{}}});
if(new URLSearchParams(location.search).get('vista')==='duena'){currentPerson='Dueña';page='overview'}
